const STRUCTURAL = new Set(['poverty-structural-barriers','financial-crisis-family-plan','physical-activity-quality-of-life-family-support','public-transport-social-inclusion-older-adults']);

const SPECIAL_SOURCE_OVERRIDES: Record<string, SourceKey[]> = {
  'privacy-information-sharing': ['talentiaGuide','lithuaniaCode','ifswEthics','sloveniaEthics'],
  'digital-ethics-confidentiality': ['talentiaGuide','lithuaniaCode','ifswEthics','avenirDe'],
  'advocacy-accountability': ['whoSdh','ifswEthics','lithuaniaMethods','talentiaGuide'],
};

function trackFor(key: string): Track {
  if (CO_CREATION.has(key)) return 'coCreation';
  if (ETHICS.has(key)) return 'ethics';
  if (FAMILY.has(key)) return 'family';
  if (COMMUNITY.has(key)) return 'community';
  if (QUALITY.has(key)) return 'quality';
  if (STRUCTURAL.has(key)) return 'structural';
  if (/ethic|right|law|code|power|confidential|digital|professional|comparative|switzerland|lithuania|finland|justice|autonomy|boundary/i.test(key)) return 'comparative';
  return 'comparative';
}

function stripTags(value: string) {
  return value.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
}

function titleFromHtml(html: string, key: string) {
  const match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  return match ? stripTags(match[1]) : key.replace(/-/g, ' ');
}

function sourceCard(key: SourceKey) {
  const source = SOURCES[key];
  return `<article class="rie-source-card"><h4><a href="${source.href}" target="_blank" rel="noopener noreferrer">${source.label}</a></h4><p><strong>كيف وصل إلينا/لماذا هو هنا:</strong> ${source.provenance}</p><p><strong>الاستخدام في هذه الموسوعة:</strong> ${source.use}</p><p class="rie-limit"><strong>حد النقل:</strong> ${source.limit}</p></article>`;
}

function sourcesFor(key: string, track: Track): SourceKey[] {
  const own = TOPICS[key]?.sources;
  const special = SPECIAL_SOURCE_OVERRIDES[key];
  return Array.from(new Set([...(own ?? []), ...(special ?? []), ...TRACK_SOURCES[track]])).slice(0, 6);
}

function defaultProfile(title: string, track: Track): TopicProfile {
  const prompts: Record<Track, TopicProfile> = {
    coCreation: { question: `كيف نترجم «${title}» إلى قرار وخطوات متفق عليها وقابلة للمراجعة؟`, practice: ['تحديد ما يهم الشخص/الأسرة والنتيجة المرغوبة قبل الأداة.', 'تعيين المسؤوليات والموارد ومؤشر التقدم.', 'مراجعة الخطة مع المستفيد وتعديلها عند ظهور معرفة جديدة.'], audit: ['هل يظهر صوت المستفيد في تعريف النتيجة؟', 'هل يمكن تتبع الخطوة التالية وسببها؟'] },
    ethics: { question: `ما المعضلة الأخلاقية الفعلية داخل «${title}»، ومن يملك أي حق أو سلطة؟`, practice: ['تحديد الحقوق والواجبات والمصالح المتعارضة.', 'تمييز القانون المحلي عن المبدأ المهني والتفضيل المؤسسي.', 'توثيق البدائل والمبرر والمراجعة المتاحة.'], audit: ['هل القرار قابل للتفسير أمام الشخص ومراجع مستقل؟', 'هل استُخدم أقل تقييد لازم للحقوق والاستقلال؟'] },
    family: { question: `كيف نجعل «${title}» مفيدًا للأسرة في حياتها اليومية لا مجرد وصف مهني؟`, practice: ['جمع أصوات الأسرة والموارد والعوائق ذات الصلة.', 'تحويل التقييم إلى أولوية وخطوة ومسؤول واضح.', 'مراجعة أثر الخطة على أفراد الأسرة لا على المستفيد المحدد فقط.'], audit: ['هل الخطة قابلة للتنفيذ ضمن موارد الأسرة؟', 'هل توجد أصوات أو أعباء أسرية لم تُرصد؟'] },
    community: { question: `كيف نربط «${title}» بشبكة موارد حقيقية ومسؤوليات قابلة للتنفيذ؟`, practice: ['تحديد الموارد الرسمية وغير الرسمية وفجوات الوصول.', 'التحقق من الأهلية واللغة والتكلفة ومسار الإحالة.', 'تعيين من يتابع الوصول ومن يعيد التخطيط عند الفشل.'], audit: ['هل المورد متاح فعليًا الآن؟', 'هل تقلل الخطة عبء التنسيق على الشخص/الأسرة؟'] },
    quality: { question: `ما المعيار القابل للملاحظة الذي يجعل «${title}» ممارسة ذات جودة؟`, practice: ['تحديد معيار ومؤشر وخط أساس.', 'جمع تغذية راجعة وملاحظة الفجوة.', 'تحويل الفجوة إلى خطة تطوير ثم إعادة القياس.'], audit: ['هل يمكن لمراجع مستقل فهم معيار الجودة؟', 'هل نتج عن التدقيق تغيير قابل للتتبع؟'] },
    structural: { question: `ما الجزء الفردي وما الجزء البنيوي داخل «${title}»؟`, practice: ['تحديد أثر الدخل والسكن والتعليم والعمل والخدمات والتمييز عند الصلة.', 'الفصل بين ما تستطيع الأسرة تغييره وما يحتاج استجابة مؤسسية.', 'ربط الدعم المباشر بمناصرة أو تعديل نظامي عندما يتكرر العائق.'], audit: ['هل الخطة تطلب ما تسمح به الموارد فعلًا؟', 'هل سُجل العائق البنيوي بدل تحويله إلى لوم فردي؟'] },
    comparative: { question: `ما الذي يمكن نقله مهنيًا من المقارنة في «${title}»، وما الذي يجب أن يبقى محليًا؟`, practice: ['تحديد المبدأ المشترك أولًا.', 'وسم كل حكم قانوني/تنظيمي ببلده ومصدره.', 'تحويل المقارنة إلى أسئلة قرار قابلة للاستخدام عربيًا.'], audit: ['هل خلطنا بين المثال الوطني والقاعدة العالمية؟', 'هل كل ادعاء إلزامي مرتبط باختصاص قانوني واضح؟'] },
  };
  return prompts[track];
}

function institutionalPageLayer(html: string, key: string) {
  const title = titleFromHtml(html, key);
  const track = trackFor(key);
  const context = TRACK_CONTEXT[track];
  const profile = TOPICS[key] ?? defaultProfile(title, track);
  const sourceKeys = sourcesFor(key, track);

  return `<section class="rawafid-institutional-evidence" ${MARKER}>
  <div class="rie-kicker">طبقة الدليل المؤسسي · تحديث ${RELEASE}</div>
  <h2>الدليل والمنطق المهني وراء «${title}»</h2>
  <p>${context.evidence}</p>
  <div class="rie-grid">
    <article><h3>السؤال الذي يجب أن تجيب عنه الممارسة</h3><p>${profile.question}</p></article>
    <article><h3>ما الذي يجب أن يظهر في التنفيذ؟</h3><ol>${profile.practice.map((item) => `<li>${item}</li>`).join('')}</ol></article>
    <article><h3>اختبار جودة سريع</h3><ul>${profile.audit.map((item) => `<li>${item}</li>`).join('')}</ul></article>
    <article><h3>حدود النقل إلى السياق العربي</h3><p>${context.transfer}</p></article>
  </div>
  <div class="rie-method-note"><h3>كيف نقرأ قوة الدليل هنا؟</h3><p>المصادر الأخلاقية ومدونات السلوك تدعم <strong>المعيار المهني ومنطق القرار</strong>، والمصادر المنهجية ودراسات الممارسة تدعم <strong>طريقة تنظيم العمل والتعلم منه</strong>. لا نحول هذا النوع من الأدلة إلى ادعاء علاجي أو سببي. وعندما تتجاوز الصفحة نطاق هذه المصادر، تبقى المراجع التخصصية الأصلية داخل الصفحة جزءًا لازمًا من سلسلة الاستدلال.</p></div>
  <h3>مصادر أصلية مرتبطة بهذه الصفحة</h3>
  <div class="rie-source-grid">${sourceKeys.map(sourceCard).join('')}</div>
  <p class="rie-disclaimer"><strong>الحوكمة:</strong> الإحالة إلى مؤسسة أو مصدر لا تعني أن المؤسسة راجعت هذه الصفحة أو اعتمدتها أو تشرف عليها أو تشارك روافد رسميًا، ما لم يوجد تصريح مكتوب صريح بذلك. الصياغة العربية هنا تحرير مستقل من روافد مع الحفاظ على المصدر والسياق وحدود النقل.</p>
</section>`;
}

function hubLayer() {
  const cards: SourceKey[] = ['sloveniaEthics','ljubljanaFamilies','talentiaGuide','avenirDe','avenirFr','lithuaniaCode','lithuaniaMethods','ifswEthics'];
  return `<section class="rawafid-institutional-evidence rie-hub" ${MARKER}>
  <div class="rie-kicker">بنية معرفية ومهنية موحدة · 2 سبتمبر 2026</div>
  <h2>كيف تستخدم قسم العمل الاجتماعي؟</h2>
  <p>هذا القسم ليس أرشيف مقالات عامة. بنيته الحالية تجمع <strong>78 دليلًا ومسارًا تطبيقيًا</strong> حول العمل مع الأفراد والأسر والمجتمع، مع طبقة أخلاقيات وحقوق، وطبقة ممارسة أسرية تشاركية، وطبقة تنسيق وجودة، ومسار مقارنة دولية. كل صفحة يجب أن تجيب عن سؤال مهني محدد، تعرض خطوات قابلة للتنفيذ، وتوضح ما يدعمه المصدر وما لا يسمح لنا باستنتاجه.</p>
  <div class="rie-grid rie-paths">
    <article><h3>1) الأسرة وعلاقة العمل</h3><p>ابدأ بخطة المساعدة التشاركية، علاقة العمل، النتائج المرغوبة، منظور القوة، الأسر متعددة التحديات ومراجعة التقدم. الأساس التطبيقي الرئيس هنا مواد كلية العمل الاجتماعي بجامعة ليوبليانا التي رشحتها لنا الجمعية السلوفينية.</p><p><a href="/evidence-guides/social-work/co-created-help-plan/"><strong>فتح خطة المساعدة التشاركية</strong></a></p></article>
    <article><h3>2) الأخلاقيات والحقوق</h3><p>استخدم مسار الأخلاقيات عندما يكون السؤال عن الكرامة، تقرير المصير، السرية، السلطة، الحدود، القرار المدعوم أو المعضلة المهنية. المسار يضع Talentia وسلوفينيا وAvenirSocial وليتوانيا بجانب IFSW مع فصل واضح للقانون الوطني.</p><p><a href="/evidence-guides/social-work/professional-ethics/"><strong>فتح مسار الأخلاقيات</strong></a></p></article>
    <article><h3>3) التنسيق والمجتمع والجودة</h3><p>للحالات التي تتقاطع فيها خدمات متعددة، انتقل إلى خرائط الموارد، الإحالة مع الاستمرارية، الاجتماعات متعددة التخصصات، المناصرة، وتدقيق خطة المساعدة. مواد PKTC التي أحالتنا إليها LSDA توسع هذا المسار إلى الكفاءات والتعلم التنظيمي.</p><p><a href="/evidence-guides/social-work/service-coordination/"><strong>فتح تنسيق الخدمات</strong></a></p></article>
    <article><h3>4) المقارنة الدولية</h3><p>المقارنة ليست لاستيراد قوانين الآخرين. نستخدمها لاكتشاف الأسئلة والمبادئ المهنية المشتركة، ثم نضع علامة صريحة على كل ما هو سويسري أو ليتواني أو فنلندي أو سلوفيني قبل أي تكييف عربي.</p><p><a href="/evidence-guides/social-work/international-comparative-practice/"><strong>فتح المسار المقارن</strong></a></p></article>
  </div>
  <div class="rie-method-note"><h3>سلم الاستدلال والتحرير</h3><ol><li><strong>مصدر أصلي:</strong> مدونة رسمية، مؤسسة مهنية، جامعة، منظمة دولية أو وثيقة منهجية أصلية.</li><li><strong>وصف أمين:</strong> نحدد هل المصدر قانون/مدونة أخلاقية/إطار ممارسة/دراسة/إرشاد، ولا نرفع رتبته.</li><li><strong>تكييف عربي مستقل:</strong> نحوّل الفكرة إلى سؤال وخطوات وأداة عملية مع التصريح بأنها ليست ترجمة أو اعتمادًا رسميًا.</li><li><strong>حدود النقل:</strong> القانون والسياسة والأهلية ومسارات الحماية والإحالة تحتاج دائمًا تحققًا محليًا.</li><li><strong>تتبّع التحديث:</strong> عند وصول مصدر أحدث من الجهة الأصلية نستبدل النسخة القديمة ونحتفظ بمصدر النسخة والتاريخ.</li></ol></div>
  <h3>خريطة المصادر المؤسسية التي بُني عليها القسم</h3>
  <div class="rie-source-grid">${cards.map(sourceCard).join('')}</div>
  <div class="rie-method-note"><h3>ماذا تغيّر في هذه المراجعة؟</h3><ul><li>اعتماد روابط AvenirSocial النهائية لعام 2026 بدل مسودة الجمعية العامة لعام 2025.</li><li>توسيع استخدام مواد LSDA/PKTC من “مقارنة أخلاقية” إلى الكفاءة، تقييم الممارسة، التطوير التنظيمي والعمل المجتمعي حيث تكون ذات صلة.</li><li>ربط كل صفحة بطبقة دليل توضح السؤال المهني، عناصر التنفيذ، اختبار الجودة، وحدود النقل.</li><li>إبقاء صفحات الطفل وكبار السن والعبء البنيوي مرتبطة أيضًا بمصادر دولية تخصصية حديثة مثل UNICEF وWHO حيث يلزم.</li></ul></div>
  <p class="rie-disclaimer"><strong>مهم:</strong> ورود اسم الجهة في هذا القسم يعني أن المصدر صادر عنها أو وصلنا بإحالة منها أو أنه مرجع دولي علني. لا يعني ذلك شراكة أو إشرافًا أو مصادقة على روافد ما لم يُذكر خلاف ذلك استنادًا إلى تصريح مكتوب.</p>
</section>`;
}

const STYLE = `<style data-rawafid-institutional-style="${RELEASE}">
.rawafid-institutional-evidence{background:#fff;border:1px solid #b8d6cc;border-radius:22px;padding:clamp(1rem,2.5vw,1.6rem);margin:1.2rem 0;box-shadow:0 12px 32px rgba(7,93,77,.06)}
.rawafid-institutional-evidence h2,.rawafid-institutional-evidence h3,.rawafid-institutional-evidence h4{color:#075d4d}.rie-kicker{display:inline-block;font-weight:800;font-size:.86rem;background:#e4f2ed;border:1px solid #c2ded4;border-radius:999px;padding:.25rem .7rem;margin-bottom:.5rem}.rie-grid,.rie-source-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:.85rem}.rie-grid>article,.rie-source-card,.rie-method-note{background:#f7fbf9;border:1px solid #d4e6df;border-radius:15px;padding:1rem}.rie-source-card h4{margin-top:0}.rie-source-card p{margin:.55rem 0}.rie-limit{border-inline-start:3px solid #8a4f0b;padding-inline-start:.65rem}.rie-method-note{margin:1rem 0}.rie-disclaimer{margin-top:1rem;padding:1rem;border-radius:14px;background:#fff8e9;border:1px solid #ead8b4}.rie-paths article{min-height:100%}.rawafid-institutional-evidence a{overflow-wrap:anywhere}
</style>`;

function patchKnownSourceUrls(html: string) {
  return html
    .split(STALE_AVENIR_DRAFT).join(FINAL_AVENIR_DE)
    .split('https://www.e-tar.lt/portal/en/legalAct/f596df101af111eeb233e8b04dc9bb3d').join('https://www.e-tar.lt/portal/lt/legalAct/f596df101af111eeb233e8b04dc9bb3d');
}

function patchHubMetadata(html: string) {
  return html
    .replace(/55 دليلًا عربيًا/g, '78 دليلًا ومسارًا عربيًا')
    .replace(/55 دليلًا/g, '78 دليلًا ومسارًا')
    .replace(/55 دليل/g, '78 دليلًا ومسارًا')
    .replace('تحديث 31 أغسطس 2026', 'تحديث 2 سبتمبر 2026');
}

function injectStyle(html: string) {
  if (html.includes('data-rawafid-institutional-style=')) return html;
  return html.includes('</head>') ? html.replace('</head>', `${STYLE}</head>`) : `${STYLE}${html}`;
}

export function enrichSocialWorkInstitutionalPage(inputHtml: string, key: string) {
  let html = patchKnownSourceUrls(inputHtml);
  if (!key) html = patchHubMetadata(html);
  if (html.includes(MARKER)) return injectStyle(html);
  html = injectStyle(html);
  const layer = key ? institutionalPageLayer(html, key) : hubLayer();
  if (html.includes('</main>')) return html.replace('</main>', `${layer}</main>`);
  if (html.includes('</body>')) return html.replace('</body>', `<main>${layer}</main></body>`);
  return `${html}${layer}`;
}

